import { takaro, data, TakaroUserError } from '@takaro/helpers';

async function main() {
    const rawColor = data.arguments.color?.trim();

    if (!rawColor) {
        throw new TakaroUserError('Usage: /setcolor ff00ff');
    }

    const color = rawColor.replace(/^#/, '').toUpperCase();

    if (!/^[0-9A-F]{6}$/.test(color)) {
        throw new TakaroUserError('Invalid color. Use a 6-digit hex code like ff00ff.');
    }

    const existingVar = await takaro.variable.variableControllerSearch({
        filters: {
            key: ['nameColor'],
            gameServerId: [data.gameServerId],
            playerId: [data.player.id],
            moduleId: [data.module.moduleId]
        }
    });

    if (existingVar.data.data.length > 0) {
        await takaro.variable.variableControllerUpdate(existingVar.data.data[0].id, {
            value: color
        });
    } else {
        await takaro.variable.variableControllerCreate({
            key: 'nameColor',
            value: color,
            gameServerId: data.gameServerId,
            playerId: data.player.id,
            moduleId: data.module.moduleId
        });
    }

    // Remove any existing gradient
    const gradientResult = await takaro.variable.variableControllerSearch({
        filters: {
            key: ['nameGradient'],
            gameServerId: [data.gameServerId],
            playerId: [data.player.id],
            moduleId: [data.module.moduleId]
        }
    });

    if (gradientResult.data.data.length > 0) {
        await takaro.variable.variableControllerUpdate(gradientResult.data.data[0].id, {
            value: ''
        });
    }

    const coloredName = '[' + color + ']' + data.player.name + '[-]';

    // FIX FOR NAMES WITH SPACES
    const safePlayerName = '"' + data.player.name.replace(/"/g, '\\"') + '"';

    await takaro.gameserver.gameServerControllerExecuteCommand(data.gameServerId, {
        command: 'ocn ' + safePlayerName + ' ' + coloredName
    });

    await data.player.pm(
        '[FE0288]Color Applied![-]\n' +
        '[FFFFFF]#' + color + '[-]\n' +
        '[D8B4FE]Your name now stands out.[-]'
    );
}

await main();

import { takaro, data, TakaroUserError } from '@takaro/helpers';

function hexToRgb(hex) {
    const clean = hex.replace(/^#/, '');
    return {
        r: parseInt(clean.substring(0, 2), 16),
        g: parseInt(clean.substring(2, 4), 16),
        b: parseInt(clean.substring(4, 6), 16)
    };
}

function rgbToHex(r, g, b) {
    return [r, g, b]
        .map(function (v) {
            return Math.max(0, Math.min(255, Math.round(v)))
                .toString(16)
                .padStart(2, '0');
        })
        .join('')
        .toUpperCase();
}

function interpolateColor(start, end, factor) {
    const s = hexToRgb(start);
    const e = hexToRgb(end);

    const r = s.r + (e.r - s.r) * factor;
    const g = s.g + (e.g - s.g) * factor;
    const b = s.b + (e.b - s.b) * factor;

    return rgbToHex(r, g, b);
}

function buildGradientName(name, color1, color2) {
    const chars = name.split('');
    let result = '';

    if (chars.length === 1) {
        return '[' + color1 + ']' + chars[0] + '[-]';
    }

    for (let i = 0; i < chars.length; i++) {
        const factor = i / (chars.length - 1);
        const color = interpolateColor(color1, color2, factor);

        // Keep spaces but don't color them
        if (chars[i] === ' ') {
            result += ' ';
        } else {
            result += '[' + color + ']' + chars[i] + '[-]';
        }
    }

    return result;
}

async function main() {
    const rawColor1 = data.arguments.color1 && data.arguments.color1.trim();
    const rawColor2 = data.arguments.color2 && data.arguments.color2.trim();

    if (!rawColor1 || !rawColor2) {
        throw new TakaroUserError('Usage: /setgradient ff00ff 00ffff');
    }

    const color1 = rawColor1.replace(/^#/, '').toUpperCase();
    const color2 = rawColor2.replace(/^#/, '').toUpperCase();

    if (!/^[0-9A-F]{6}$/.test(color1) || !/^[0-9A-F]{6}$/.test(color2)) {
        throw new TakaroUserError('Both colors must be 6-digit hex codes like ff00ff');
    }

    const gradientValue = color1 + ',' + color2;

    const existingVar = await takaro.variable.variableControllerSearch({
        filters: {
            key: ['nameGradient'],
            gameServerId: [data.gameServerId],
            playerId: [data.player.id],
            moduleId: [data.module.moduleId]
        }
    });

    if (existingVar.data.data.length > 0) {
        await takaro.variable.variableControllerUpdate(existingVar.data.data[0].id, {
            value: gradientValue
        });
    } else {
        await takaro.variable.variableControllerCreate({
            key: 'nameGradient',
            value: gradientValue,
            gameServerId: data.gameServerId,
            playerId: data.player.id,
            moduleId: data.module.moduleId
        });
    }

    // Clear any solid color if one exists
    const solidResult = await takaro.variable.variableControllerSearch({
        filters: {
            key: ['nameColor'],
            gameServerId: [data.gameServerId],
            playerId: [data.player.id],
            moduleId: [data.module.moduleId]
        }
    });

    if (solidResult.data.data.length > 0) {
        await takaro.variable.variableControllerUpdate(solidResult.data.data[0].id, {
            value: ''
        });
    }

    const gradientName = buildGradientName(data.player.name, color1, color2);

    // FIX FOR NAMES WITH SPACES
    const safePlayerName = '"' + data.player.name.replace(/"/g, '\\"') + '"';

    await takaro.gameserver.gameServerControllerExecuteCommand(data.gameServerId, {
        command: 'ocn ' + safePlayerName + ' ' + gradientName
    });

    await data.player.pm(
        '[FE0288]Gradient Applied![-]\n' +
        '[FFFFFF]#' + color1 + ' [C77DFF]->[-] #' + color2 + '[-]\n' +
        '[D8B4FE]Your name now stands out.[-]'
    );
}

await main();

