        .map(v => Math.max(0, Math.min(255, Math.round(v))).toString(16).padStart(2, '0'))
        .join('')
        .toUpperCase();
}

function interpolateColor(start, end, factor) {
    const s = hexToRgb(start);
    const e = hexToRgb(end);

    const r = s.r + (e.r - s.r) * factor;
    const g = s.g + (e.g - s.g) * factor;
    const b = s.b + (e.b - s.b) * factor;

    return rgbToHex(r, g, b);
}

function buildGradientName(name, color1, color2) {
    const chars = name.split('');
    let result = '';

    if (chars.length === 1) {
        return `[${color1}]${chars[0]}[-]`;
    }

    for (let i = 0; i < chars.length; i++) {
        const factor = i / (chars.length - 1);
        const color = interpolateColor(color1, color2, factor);
        result += `[${color}]${chars[i]}[-]`;
    }

    return result;
}

function quotePlayerName(name) {
    return '"' + String(name).replace(/"/g, '\"') + '"';
}

async function main() {
    const { gameServerId, player, module: mod } = data;

    const gradientResult = await takaro.variable.variableControllerSearch({
        filters: {
            key: ['nameGradient'],
            gameServerId: [gameServerId],
            playerId: [player.id],
            moduleId: [mod.moduleId]
        }
    });

    const savedGradient = gradientResult.data.data[0];

    if (savedGradient && savedGradient.value) {
        const [color1, color2] = savedGradient.value.split(',');

        if (color1 && color2) {
            const gradientName = buildGradientName(player.name, color1, color2);

            await takaro.gameserver.gameServerControllerExecuteCommand(gameServerId, {
                command: 'ocn ' + quotePlayerName(player.name) + ' ' + gradientName
            });

            return;
        }
    }

    const colorResult = await takaro.variable.variableControllerSearch({
        filters: {
            key: ['nameColor'],
            gameServerId: [gameServerId],
            playerId: [player.id],
            moduleId: [mod.moduleId]
        }
    });

    const savedColor = colorResult.data.data[0];

    if (savedColor && savedColor.value) {
        const coloredName = `[${savedColor.value}]${player.name}[-]`;

        await takaro.gameserver.gameServerControllerExecuteCommand(gameServerId, {
            command: `ocn ${player.name} ${coloredName}`
        });
    }
}

await main();
